    61  static gboolean
    62  fu_uswid_firmware_parse(FuFirmware *firmware,
    63                          GInputStream *stream,
    64                          gsize offset,
    65                          FwupdInstallFlags flags,
    66                          GError **error)
    67  {
    68          FuUswidFirmware *self = FU_USWID_FIRMWARE(firmware);
    69          FuUswidFirmwarePrivate *priv = GET_PRIVATE(self);
    70          guint16 hdrsz;
    71          guint32 payloadsz;
    72          g_autoptr(FuStructUswid) st = NULL;
    73          g_autoptr(GBytes) payload = NULL;
    74
    75          /* unpack */
    76          st = fu_struct_uswid_parse_stream(stream, offset, error);
    77          if (st == NULL)
    78                  return FALSE;
    79
    80          /* hdrver */
    81          priv->hdrver = fu_struct_uswid_get_hdrver(st);
    82          if (priv->hdrver < FU_USWID_FIRMARE_MINIMUM_HDRVER) {
    83                  g_set_error_literal(error,
    84                                      FWUPD_ERROR,
    85                                      FWUPD_ERROR_NOT_SUPPORTED,
    86                                      "header version was unsupported");
    87                  return FALSE;
    88          }
    89
    90          /* hdrsz+payloadsz */
    91          hdrsz = fu_struct_uswid_get_hdrsz(st);
    92          payloadsz = fu_struct_uswid_get_payloadsz(st);
    93          if (payloadsz == 0x0) {
    94                  g_set_error_literal(error,
    95                                      FWUPD_ERROR,
    96                                      FWUPD_ERROR_NOT_SUPPORTED,
    97                                      "payload size is invalid");
    98                  return FALSE;
    99          }
   100          fu_firmware_set_size(firmware, hdrsz + payloadsz);
   101
   102          /* flags */
   103          if (priv->hdrver >= 0x03) {
   104                  if (fu_struct_uswid_get_flags(st) & FU_USWID_HEADER_FLAG_COMPRESSED) {
   105                          priv->compression = fu_struct_uswid_get_compression(st);
   106                  } else {
   107                          priv->compression = FU_USWID_PAYLOAD_COMPRESSION_NONE;
   108                  }
   109          } else if (priv->hdrver >= 0x02) {
   110                  priv->compression = fu_struct_uswid_get_flags(st) & FU_USWID_HEADER_FLAG_COMPRESSED
   111                                          ? FU_USWID_PAYLOAD_COMPRESSION_ZLIB
   112                                          : FU_USWID_PAYLOAD_COMPRESSION_NONE;
   113          } else {
   114                  priv->compression = FU_USWID_PAYLOAD_COMPRESSION_NONE;
   115          }
   116
   117          /* zlib stream */
   118          if (priv->compression == FU_USWID_PAYLOAD_COMPRESSION_ZLIB) {
   119                  g_autoptr(GConverter) conv = NULL;
   120                  g_autoptr(GInputStream) istream1 = NULL;
   121                  g_autoptr(GInputStream) istream2 = NULL;
   122                  conv = G_CONVERTER(g_zlib_decompressor_new(G_ZLIB_COMPRESSOR_FORMAT_ZLIB));
   123                  istream1 = fu_partial_input_stream_new(stream, offset + hdrsz, payloadsz);
   124                  istream2 = g_converter_input_stream_new(istream1, conv);
   125                  payload = fu_input_stream_read_bytes(istream2, 0, G_MAXSIZE, error);
   126                  if (payload == NULL)
   127                          return FALSE;
   128          } else if (priv->compression == FU_USWID_PAYLOAD_COMPRESSION_LZMA) {
   129                  g_autoptr(GBytes) payload_tmp = NULL;
   130                  payload_tmp = fu_input_stream_read_bytes(stream, offset + hdrsz, payloadsz, error);
   131                  if (payload_tmp == NULL)
   132                          return FALSE;
   133                  payload = fu_lzma_decompress_bytes(payload_tmp, error);
   134                  if (payload == NULL)
   135                          return FALSE;
   136          } else if (priv->compression == FU_USWID_PAYLOAD_COMPRESSION_NONE) {
   137                  payload = fu_input_stream_read_bytes(stream, offset + hdrsz, payloadsz, error);
   138                  if (payload == NULL)
   139                          return FALSE;
   140          } else {
   141                  g_set_error(error,
   142                              FWUPD_ERROR,
   143                              FWUPD_ERROR_NOT_SUPPORTED,
   144                              "compression format 0x%x is not supported",
   145                              priv->compression);
   146                  return FALSE;
   147          }
   148
   149          /* payload */
   150          payloadsz = g_bytes_get_size(payload);
   105  {
   106          g_set_error_literal(error,
   107                              FWUPD_ERROR,
   108                              FWUPD_ERROR_NOT_SUPPORTED,
   109                              "cannot truncate FuPartialInputStream");
   110          return FALSE;
   111  }
