   133   * Since: 2.0.0
   134   **/
   135  GInputStream *
   136  fu_partial_input_stream_new(GInputStream *stream, gsize offset, gsize size)
   137  {
   138          g_autoptr(FuPartialInputStream) self = g_object_new(FU_TYPE_PARTIAL_INPUT_STREAM, NULL);
